syn::Stmt::Item(Item::Use(nested)) => {
    let (names, has_glob) = use_item_bindings(&nested.tree);
    hoisted.extend(names);
    conservative_unresolved |= has_glob;
}
syn::Stmt::Item(syn::Item::ForeignMod(foreign)) => {
    // A block-local foreign module's `fn`/`static` items put their names in
    // the enclosing block's value namespace, exactly as a block-local
    // `fn`/`static` does, so they shadow a same-named module-level function
    // for a naked call in this block. A foreign `type` alias is
    // type-namespace only (like a named-field struct) and never shadows.
    for item in &foreign.items {
        match item {
            syn::ForeignItem::Fn(decl) => {
                hoisted.push(decl.sig.ident.to_string());
            }
            syn::ForeignItem::Static(decl) => {
                hoisted.push(decl.ident.to_string());
            }
            _ => {}
        }
    }
}
